/* saleson.shop.user.UserMapper.mergeUserRole */
MERGE INTO OP_USER_ROLE USING db_root ON (USER_ID = #{userId} AND AUTHORITY = #{authority})

WHEN MATCHED THEN
  UPDATE SET
  	USER_ID = #{userId},
  	AUTHORITY = #{authority}
  WHERE USER_ID = #{userId} AND AUTHORITY = #{authority}

WHEN NOT MATCHED THEN
	INSERT (USER_ID, AUTHORITY)
	VALUES (#{userId}, #{authority})

