/* saleson.shop.user.UserMapper.getOpUserBirthdayDecSubstrList */
SELECT SUBSTR(CREATED_DATE, 1, 8) AS paramDate FROM OP_USER WHERE STATUS_CODE ='9' AND USER_ID > (SELECT NVL(MAX(USER_ID),'0000000') FROM OP_USER_BIRTHDAY)
AND CREATED_DATE IS NOT NULL
GROUP BY SUBSTR(CREATED_DATE, 1, 8)
ORDER BY SUBSTR(CREATED_DATE, 1, 8) ASC;
